 || string.IsNullOrEmpty(Environment.GetEnvironmentVariable("Email__DevelopmentPickupDirectory"))) throw new Exception("Use an isolated database and local message capture only.");
var checks=0;void Check(bool value,string text){if(!value)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
await using var factory=new WebApplicationFactory<AccountController>();
using var client=factory.CreateClient(new WebApplicationFactoryClientOptions {AllowAutoRedirect=false,BaseAddress=new Uri("https://localhost")});
Check((await client.GetAsync("/Admin")).StatusCode==HttpStatusCode.Redirect,"anonymous visitors cannot read dashboard statistics");
using var scope=factory.Services.CreateScope();var services=scope.ServiceProvider;var db=services.GetRequiredService<ApplicationDbContext>();var zone=services.GetRequiredService<UserTimeZone>();zone.Use("America/New_York");
var clock=new DashboardClock();await using var transaction=await db.Database.BeginTransactionAsync();
var prefix="dashboard."+Guid.NewGuid().ToString("N")[..8];
var admin=new ApplicationUser {Email=prefix+".admin@example.test",DisplayName="Dashboard administrator",JoinedDate=new DateTime(2025,1,1)};
db.Users.Add(admin);db.Admins.Add(new Admin {UserId=admin.Id});await db.SaveChangesAsync();
var controller=ActivatorUtilities.CreateInstance<AdminController>(services);controller.ControllerContext=new ControllerContext {HttpContext=new DefaultHttpContext {User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,admin.Id)},"data-test"))}};
async Task<AdminOverviewModel> Overview(int days=7)=>(AdminOverviewModel)((ViewResult)await controller.Index(clock,days)).Model!;
var before=await Overview();var start=zone.StartOfDayUtc(before.From);var end=zone.StartOfDayUtc(before.To.AddDays(1));
Check(before.From==new DateOnly(2026,3,3)&&before.To==new DateOnly(2026,3,9)&&before.Activity.Count==7,"selected period uses the administrator's local calendar dates");
Check(zone.StartOfDayUtc(new DateOnly(2026,3,9))-zone.StartOfDayUtc(new DateOnly(2026,3,8))==TimeSpan.FromHours(23),"test period includes the actual 23-hour DST transition");
ApplicationUser User(string suffix,DateTime joined)=>new(){Email=prefix+"."+suffix+"@example.test",DisplayName=prefix+" "+suffix,JoinedDate=joined};
var a=User("a",start);var b=User("b",end.AddTicks(-1));var instructor=User("instructor",end);var unassigned=User("unassigned",start.AddTicks(-1));
b.IsDisabled=true;db.Users.AddRange(a,b,instructor,unassigned);db.Students.AddRange(new Student{UserId=a.Id},new Student{UserId=b.Id},new Student{UserId=instructor.Id},new Student{UserId=admin.Id});db.Instructors.Add(new Instructor{UserId=instructor.Id});await db.SaveChangesAsync();
void Login(ApplicationUser user,DateTime utc,string outcome="Signed in")=>db.LoginRecords.Add(new LoginRecord{UserId=user.Id,OccurredUtc=utc,Outcome=outcome,Device="Disposable dashboard fixture",IpAddress="192.0.2.12"});
Login(a,start);Login(a,start.AddHours(1));Login(a,start.AddTicks(-1));Login(b,new DateTime(2026,3,8,4,59,0,DateTimeKind.Utc));Login(b,new DateTime(2026,3,8,5,1,0,DateTimeKind.Utc));Login(b,new DateTime(2026,3,8,10,0,0,DateTimeKind.Utc));Login(unassigned,start,"Failed");Login(unassigned,start,"Verification failed");Login(unassigned,end);
var course=new Course{Title=prefix+" Current course",InstructorId=instructor.Id,IsPublished=true,ReviewStatus=CourseReviewStatus.Approved};var previousCourse=new Course{Title=prefix+" Previous course",InstructorId=instructor.Id};db.Courses.AddRange(course,previousCourse);await db.SaveChangesAsync();
db.Enrollments.AddRange(new Enrollment{CourseId=course.CourseId,UserId=a.Id,EnrolledDate=start},new Enrollment{CourseId=course.CourseId,UserId=b.Id,EnrolledDate=end.AddTicks(-1)},new Enrollment{CourseId=course.CourseId,UserId=instructor.Id,EnrolledDate=start.AddTicks(-1)},new Enrollment{CourseId=previousCourse.CourseId,UserId=a.Id,EnrolledDate=start.AddDays(-1)},new Enrollment{CourseId=previousCourse.CourseId,UserId=b.Id,EnrolledDate=end});
db.SupportTickets.AddRange(new SupportTicket{UserId=a.Id,Subject="Awaiting fixture",Status="Awaiting admin"},new SupportTicket{UserId=b.Id,Subject="Reply fixture",Status="Awaiting user"},new SupportTicket{UserId=instructor.Id,Subject="Resolved fixture",Status="Resolved"});
db.SecurityAlerts.AddRange(new SecurityAlert{UserId=a.Id,EventKey=prefix+".new",Title=prefix+" New alert",Status="New"},new SecurityAlert{UserId=b.Id,EventKey=prefix+".investigating",Title=prefix+" Investigating alert",Status="Investigating"},new SecurityAlert{UserId=instructor.Id,EventKey=prefix+".resolved",Title=prefix+" Resolved alert",Status="Resolved"});
db.InstructorApplications.Add(new InstructorApplication{UserId=a.Id,Revision=1,FullName="Dashboard applicant",Status=ApplicationStatus.Pending});
var eventTime=(await db.AdminActivities.Select(x=>(DateTime?)x.OccurredUtc).MaxAsync()??DateTime.UtcNow).AddMinutes(1);
for(var i=0;i<6;i++)db.AdminActivities.Add(new AdminActivity{ActorUserId=admin.Id,TargetType="User",TargetId=a.Id,TargetName="Original target name",Action=prefix+" action "+i,OccurredUtc=eventTime});
db.AdminActivities.Add(new AdminActivity{ActorUserId=admin.Id,TargetType="Account security",TargetId=a.Id,Action=prefix+" account security",OccurredUtc=eventTime.AddMinutes(1)});await db.SaveChangesAsync();
var model=await Overview();
Check(model.Users==before.Users+4&&model.DisabledUsers==before.DisabledUsers+1,"current account and disabled totals come from persisted users");
Check(model.NewUsers==before.NewUsers+2,"new-account totals include the start and exclude the next local day");
Check(model.ActiveUsers==before.ActiveUsers+2,"active users count distinct successful sign-ins, not attempts or enabled accounts");
Check(model.PreviousActiveUsers==before.PreviousActiveUsers+1,"previous-period activity excludes the selected period's first instant");
Check(model.Activity[0].Users==before.Activity[0].Users+1,"repeat sign-ins count once per user per local day");
Check(model.Activity.Single(x=>x.Date==new DateOnly(2026,3,7)).Users==before.Activity.Single(x=>x.Date==new DateOnly(2026,3,7)).Users+1,"late UTC events remain in the previous local calendar day");
Check(model.Activity.Single(x=>x.Date==new DateOnly(2026,3,8)).Users==before.Activity.Single(x=>x.Date==new DateOnly(2026,3,8)).Users+1,"DST-day events group correctly and repeated activity remains distinct");
Check(model.PendingSupport==before.PendingSupport+1,"pending requests exclude awaiting-user and resolved conversations");
Check(model.OpenAlerts==before.OpenAlerts+2,"open alerts include New and Investigating but exclude Resolved");
Check(model.PendingApplications==before.PendingApplications+1,"pending Instructor applications remain visible in the review queue");
Check(model.Courses==before.Courses+2&&model.PublishedCourses==before.PublishedCourses+1,"course statistics distinguish published and draft courses");
var enrolments=model.CourseEnrollments.Single(x=>x.CourseId==course.CourseId);Check(enrolments.Current==2&&enrolments.Previous==1,"course comparison counts equal local-calendar periods without including the next day");
Check(model.CourseEnrollments.Count<=5&&model.CourseEnrollments.Select(c=>c.Current).SequenceEqual(model.CourseEnrollments.Select(c=>c.Current).OrderDescending()),"course chart limits to five and orders by selected-period demand");
Check(model.Roles.Sum(r=>r.Count)==model.Users,"role chart counts each account once even with multiple role markers");
Check(model.Roles.Single(r=>r.Role==AccountRoles.Admin).Count==before.Roles.Single(r=>r.Role==AccountRoles.Admin).Count,"Admin role takes precedence over a retained Student marker");
