Check(model.RecentActions.Count==5&&model.RecentActions.All(x=>x.Action.StartsWith(prefix+" action "))&&!model.RecentActions.Any(x=>x.Action.EndsWith("action 0")),"recent actions show five management events in stable newest-first order");
Check(model.UserNames[admin.Id]==admin.DisplayName&&AuditPresentation.TargetName(model.RecentActions[0],model.UserNames)==a.DisplayName,"recent audit rows resolve current actor and account target names");
var open=(SecurityOverviewModel)((ViewResult)await controller.Security("open")).Model!;Check(open.Total==model.OpenAlerts&&open.Alerts.All(x=>x.Status!="Resolved"),"security queue link uses a matching open-alert filter");
